<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\Patient;use App\Models\Pharmacy;use App\Models\PharmacyOrder;use App\Services\Notification\ClinicNotificationDispatcher;use Illuminate\Http\Request;
class DeliveryTrackingController{private function order(string $n):PharmacyOrder{$o=PharmacyOrder::with(['pharmacy','patient.user'])->where('order_number',$n)->orWhere('id',$n)->firstOrFail();$u=auth()->user();$p=Patient::where('user_id',$u->id)->first();$ph=Pharmacy::where('user_id',$u->id)->first();abort_unless($u->isAdmin()||$p?->id===$o->patient_id||$ph?->id===$o->pharmacy_id,403);return $o;}private function metrics($a,$b,$c,$d){if(null===$a||null===$b||null===$c||null===$d)return[null,null];$r=6371;$x=deg2rad($c-$a);$y=deg2rad($d-$b);$h=sin($x/2)**2+cos(deg2rad($a))*cos(deg2rad($c))*sin($y/2)**2;$km=2*$r*asin(min(1,sqrt($h)));return[round($km,2),(int)ceil($km/25*60)];}public function show(string $n){$o=$this->order($n);[$km,$eta]=$this->metrics($o->courier_latitude,$o->courier_longitude,$o->delivery_latitude,$o->delivery_longitude);return response()->json(['success'=>true,'data'=>['order_number'=>$o->order_number,'status'=>$o->status,'courier'=>['name'=>$o->courier_name,'phone'=>$o->courier_phone,'latitude'=>$o->courier_latitude,'longitude'=>$o->courier_longitude],'destination'=>['latitude'=>$o->delivery_latitude,'longitude'=>$o->delivery_longitude,'address'=>$o->delivery_address],'distance_km'=>$km,'eta_minutes'=>$eta,'last_location_at'=>$o->last_location_at]]);}public function update(Request $r,string $n){$o=$this->order($n);$u=auth()->user();abort_unless($u->isAdmin()||Pharmacy::where('user_id',$u->id)->whereKey($o->pharmacy_id)->exists(),403);$d=$r->validate(['courier_name'=>'nullable|string|max:120','courier_phone'=>'nullable|string|max:30','courier_latitude'=>'required|numeric|between:-90,90','courier_longitude'=>'required|numeric|between:-180,180','delivery_latitude'=>'nullable|numeric|between:-90,90','delivery_longitude'=>'nullable|numeric|between:-180,180']);$o->update([...$d,'last_location_at'=>now()]);if($o->patient?->user)app(ClinicNotificationDispatcher::class)->send(null,'pharmacy.location_updated',$o->patient->user,['number'=>$o->order_number],'رهگیری سفارش','موقعیت سفارش {number} به‌روزرسانی شد.');return $this->show($n);}}
